<script setup>
import { computed, ref, watch } from 'vue'
import { Search, Plus, ArrowUpRight, ChevronLeft, ChevronRight, FileSearch, ArrowUp, ArrowDown, ArrowUpDown, X } from 'lucide-vue-next'
import StatusBadge from '../components/StatusBadge.vue'
import { money, label, date, day, identifier } from '../services/api'
const props = defineProps({ module: String, rows: Array, pagination: Object, query: Object, clients: Array, companies: { type: Array, default: () => [] }, can: Function })
const emit = defineEmits(['action','open','query'])
const search = ref(props.query?.q || '')
let timer
watch(() => props.module, () => { search.value = '' })
// Searching happens in the API (all pages), a moment after the person stops typing.
watch(search, value => { clearTimeout(timer); timer = setTimeout(() => { if (value !== (props.query?.q || '')) emit('query', { q: value.trim() }) }, 450) })
const customer = id => props.clients.find(x => identifier(x) === id)?.nombre || 'Cliente registrado'
const company = (id, name) => name || props.companies.find(x => identifier(x) === id)?.nombre || 'Empresa'
// Each column: title and, when the API can order by it, its field.
const configurations = {
  solicitudes: { title:'Gestiones',subtitle:'Buzón de las gestiones que los clientes solicitan desde Banca Virtual: da seguimiento, define las condiciones y aprueba el producto.',columns:[['GESTIÓN / CLIENTE','folio'],['PRODUCTO','producto'],['MONTO SOLICITADO','limite_solicitado_centavos'],['ESTADO','estado'],['RECIBIDA','created_at']],states:['en_evaluacion','emitida'],dates:true },
  creditos: { title:'Préstamos',subtitle:'Préstamos desembolsados desde la cuenta concentradora, con sus cuotas, pagos y saldo pendiente.',columns:[['REFERENCIA / TITULAR','referencia'],['MONTO','limite_centavos'],['CUOTAS PAGADAS'],['PRÓXIMO PAGO'],['SALDO DE CAPITAL','saldo_centavos'],['ESTADO','estado']],states:['vigente','pagado'],dates:true },
  cuentas: { title:'Cuentas bancarias',subtitle:'Consulta saldos y movimientos de cuentas de ahorro y monetarias.',create:'Crear cuenta',permission:'cuentas.write',columns:[['CUENTA / TITULAR','numero'],['TIPO','tipo'],['SALDO DISPONIBLE','saldo_centavos'],['ESTADO','estado'],['APERTURA','created_at']],states:['activa','bloqueada'],dates:true },
  tarjetas: { title:'Tarjetas emitidas',subtitle:'Límites, consumos, fechas de corte y cargo automático de cada tarjeta.',columns:[['REFERENCIA / TITULAR','referencia'],['PRODUCTO','producto'],['LÍMITE','limite_centavos'],['CORTE / PAGO'],['DEUDA ACTUAL','principal_centavos'],['ESTADO','estado']],states:['activa','bloqueada'] },
  clientes: { title:'Directorio de clientes',subtitle:'Todos los usuarios registrados en Banca Virtual y los clientes atendidos en agencia. El DPI vincula ambos.',create:'Registrar cliente',permission:'clientes.write',columns:[['CLIENTE','nombre'],['DPI'],['CORREO','email'],['TELÉFONO'],['NIT'],['INGRESO MENSUAL','ingreso_centavos'],['REGISTRO','created_at']],states:['agencia','banca_virtual'],stateLabel:'Todos los orígenes',dates:true,placeholder:'Nombre, correo, NIT, teléfono o DPI completo…' },
  productos: { title:'Productos y políticas',subtitle:'Consulta del catálogo de cuentas, tarjetas y préstamos con sus políticas. La información está guardada en el sistema.',columns:[['PRODUCTO','name'],['TIPO','type'],['TASA ANUAL','annual_bps'],['LÍMITE MÁXIMO','max_limit_cents'],['ESTADO']] },
  usuarios: { title:'Usuarios del banco',subtitle:'Personal del banco: Administrador, Mixto (Operaciones + Banca corporativa), Operador (Operaciones) y Corporativo (Banca corporativa). Los usuarios de cada empresa se administran en Banca corporativa → Empresas.',create:'Crear usuario',permission:'usuarios.write',columns:[['USUARIO','name'],['CORREO','email'],['ROL','role'],['ESTADO'],['REGISTRO','created_at']],states:['administrador','mixto','operador','corporativo'],stateLabel:'Todos los roles' },
  empresas: { title:'Empresas',subtitle:'Banca corporativa, separada de la banca personal: cada empresa con sus cuentas, sus usuarios corporativos y sus colaboradores.',create:'Registrar empresa',permission:'empresas.write',columns:[['EMPRESA / RAZÓN SOCIAL','nombre'],['CUENTA DE PLANILLAS'],['SALDO EN CUENTAS'],['USUARIOS'],['REGISTRO','created_at']],placeholder:'Nombre comercial, razón social o NIT…' },
  planillas: { title:'Planillas',subtitle:'Carga la planilla, revísala y autorízala: el pago se acredita al instante en la cuenta de cada colaborador.',create:'Cargar planilla',permission:'planillas.write',columns:[['PLANILLA / EMPRESA','nombre'],['COLABORADORES'],['TOTAL','total_centavos'],['ESTADO','estado'],['REGISTRO','created_at']],states:['pendiente_autorizacion','pagada'],dates:true },
  movimientos: { title:'Transacciones',subtitle:'Registro global de movimientos de todas las cuentas: depósitos, transferencias, planillas, préstamos y pagos.',columns:[['FECHA','created_at'],['CUENTA / TITULAR'],['TIPO','tipo'],['CONCEPTO'],['IMPORTE','importe_centavos'],['SALDO DESPUÉS']],states:['deposito','retiro','transferencia','planilla','desembolso_prestamo','pago_prestamo','pago_servicio','pago_tarjeta','interes_ahorro'],stateLabel:'Todos los tipos',dates:true,placeholder:'Concepto, número de cuenta o titular…' },
  colaboradores: { title:'Colaboradores de empresas',subtitle:'Clientes del banco asignados a una empresa, con su puesto, salario y la cuenta donde reciben la planilla.',create:'Asignar colaborador',permission:'colaboradores.write',columns:[['COLABORADOR / EMPRESA','nombre'],['PUESTO','puesto'],['SALARIO','salario_centavos'],['CUENTA DE PAGO'],['REGISTRO','created_at']] },
  bitacora: { title:'Bitácora de gestiones',subtitle:'Historial firmado de cada gestión: aprobaciones y pagos. Solo lectura.',columns:[['ACCIÓN','action'],['SOLICITUD'],['ESTADO','estado'],['RESPONSABLE'],['FECHA','created_at']],dates:true },
  seguridad: { title:'Actividad y seguridad',subtitle:'Accesos, cambios de permisos y operaciones registradas.',columns:[['ACCIÓN','action'],['RESPONSABLE'],['ORIGEN'],['FECHA','created_at']],dates:true },
}
const config = computed(() => configurations[props.module])
const filtered = computed(() => props.rows)
const active = computed(() => Boolean(props.query?.q || props.query?.estado || props.query?.desde || props.query?.hasta))
function sortBy(field) {
  if (!field) return
  const same = props.query.orden === field
  emit('query', { orden: field, direccion: same && props.query.direccion === 'asc' ? 'desc' : 'asc' })
}
function clear() { search.value = ''; emit('query', { q: '', estado: '', desde: '', hasta: '', orden: '', direccion: '' }) }
function cells(r) {
 switch(props.module) {
  case 'solicitudes': return [[r.folio,customer(r.cliente_id)],label(r.producto),money(r.limite_solicitado_centavos),{badge:r.estado},date(r.created_at)]
  case 'creditos': return [[r.referencia,customer(r.cliente_id)],money(r.limite_centavos),r.cuotas_total ? `${r.cuotas_pagadas} de ${r.cuotas_total}${r.cuotas_vencidas ? ` · ${r.cuotas_vencidas} vencida(s)` : ''}` : '—',r.proxima_cuota ? `${money(r.proxima_cuota.monto_centavos)} · ${day(r.proxima_cuota.fecha_vencimiento)}` : '—',money(r.saldo_centavos),{badge:r.estado}]
  case 'cuentas': return [[r.numero,customer(r.cliente_id)],label(r.tipo),money(r.saldo_centavos),{badge:r.estado},date(r.created_at)]
  case 'tarjetas': return [[r.referencia,customer(r.cliente_id)],label(r.producto),money(r.limite_centavos),r.dia_corte ? `Corte ${r.dia_corte} · pago ${r.dia_pago}` : (r.tipo === 'debito' ? 'Débito' : '—'),money(r.principal_centavos+r.interes_centavos),{badge:r.estado}]
  case 'clientes': return [[r.nombre,r.acceso_app ? 'Con acceso a Banca Virtual' : 'Sin acceso a la app'],r.dpi_enmascarado,r.email,r.telefono || '—',r.nit || '—',r.ingreso_centavos == null ? '—' : money(r.ingreso_centavos),date(r.created_at)]
  case 'productos': return [[r.name,r.code],label(r.type),r.annual_bps == null ? 'Se define al aprobar' : `${r.annual_bps/100}%`,r.max_limit_cents == null ? 'Según evaluación' : money(r.max_limit_cents),{badge:r.active}]
  case 'usuarios': return [r.name,r.email,r.role==='empresa' ? `Empresa · ${company(r.empresa_id)}` : label(r.role),{badge:r.active},date(r.created_at)]
  case 'empresas': return [[r.nombre,`${r.razon_social && r.razon_social !== r.nombre ? `${r.razon_social} · ` : ''}NIT ${r.nit}`],r.cuenta_numero || '—',money(r.saldo_total_centavos),r.representantes_total ?? r.miembros?.length ?? 0,date(r.created_at)]
  case 'planillas': return [[r.nombre,r.ultimo_error || company(r.empresa_id, r.empresa_nombre)],r.pagos?.length,money(r.total_centavos),{badge:r.estado},date(r.created_at)]
  case 'movimientos': return [date(r.created_at),[r.cuenta_numero || '—',r.cuenta_interna ? (r.cuenta_nombre || 'Cuenta interna del banco') : (r.cliente_nombre || customer(r.cliente_id))],label(r.tipo),r.concepto,money(r.importe_centavos),r.saldo_centavos == null ? '—' : money(r.saldo_centavos)]
  case 'colaboradores': return [[r.nombre,company(r.empresa_id, r.empresa_nombre)],r.puesto,money(r.salario_centavos),r.cuenta_numero,date(r.created_at)]
  case 'bitacora': return [label(r.action),r.solicitud_id,{badge:r.estado},r.actor,date(r.created_at)]
  case 'seguridad': return [label(r.action),r.actor,r.ip,date(r.created_at)]
 }
}
</script>
<template><section><div class="section-heading"><div><h2>{{ config.title }}</h2><p>{{ config.subtitle }}</p></div><div class="heading-actions"><button v-if="config.create && can(config.permission)" class="primary" @click="$emit('action', module)"><Plus :size="17"/>{{ config.create }}</button></div></div><div v-if="module === 'cuentas'" class="action-strip"><button v-if="can('dinero.write')" class="secondary" @click="$emit('action','transferencia')">Transferir entre cuentas <ArrowUpRight :size="16"/></button><button v-if="can('caja.write')" class="secondary" @click="$emit('action','caja')">Fondeo o retiro <ArrowUpRight :size="16"/></button></div><section class="panel records-panel"><div class="table-toolbar"><label class="search-box"><Search :size="17"/><input v-model="search" type="search" :placeholder="config.placeholder || 'Buscar en todos los registros…'" aria-label="Buscar en todos los registros"></label><select v-if="config.states" :value="query.estado" aria-label="Filtrar" @change="$emit('query',{estado:$event.target.value})"><option value="">{{ config.stateLabel || 'Todos los estados' }}</option><option v-for="s in config.states" :key="s" :value="s">{{ s === 'banca_virtual' ? 'Banca Virtual' : s === 'agencia' ? 'Agencia' : label(s) }}</option></select><div v-if="config.dates" class="date-filter"><label>Desde<input type="date" :value="query.desde" @change="$emit('query',{desde:$event.target.value})"></label><label>Hasta<input type="date" :value="query.hasta" :min="query.desde || undefined" @change="$emit('query',{hasta:$event.target.value})"></label></div><button v-if="active" class="text-button" @click="clear"><X :size="15"/>Limpiar</button><span class="record-count">{{ pagination?.total || 0 }} registros</span></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th v-for="[title, field] in config.columns" :key="title" :aria-sort="query.orden === field ? (query.direccion === 'asc' ? 'ascending' : 'descending') : undefined"><button v-if="field" class="sort-button" :class="{sorted: query.orden === field}" @click="sortBy(field)">{{ title }}<ArrowUp v-if="query.orden === field && query.direccion === 'asc'" :size="13"/><ArrowDown v-else-if="query.orden === field" :size="13"/><ArrowUpDown v-else :size="13"/></button><template v-else>{{ title }}</template></th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><tr v-for="row in filtered" :key="identifier(row)" class="clickable-row" @click="$emit('open',row)"><td v-for="(cell,index) in cells(row)" :key="index" :data-label="config.columns[index][0]"><span v-if="Array.isArray(cell)" class="stack-cell"><b>{{ cell[0] }}</b><small>{{ cell[1] }}</small></span><StatusBadge v-else-if="cell !== null && typeof cell === 'object'" :value="cell.badge"/><span v-else>{{ cell }}</span></td><td class="cell-action"><button class="icon-button" aria-label="Ver detalles" @click.stop="$emit('open',row)"><ArrowUpRight :size="18"/></button></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><FileSearch :size="32"/><h3>{{ active ? 'Sin coincidencias' : 'Todavía no hay registros' }}</h3><p>{{ active ? 'Prueba con otro término o cambia los filtros.' : 'Los nuevos registros aparecerán en esta sección.' }}</p></div></div><div class="pagination"><span>Página {{ pagination?.current_page || 1 }} de {{ pagination?.last_page || 1 }}</span><div><button class="secondary compact" :disabled="!pagination || pagination.current_page <= 1" aria-label="Página anterior" @click="$emit('query',{page:pagination.current_page - 1})"><ChevronLeft :size="17"/></button><button class="secondary compact" :disabled="!pagination || pagination.current_page >= pagination.last_page" aria-label="Página siguiente" @click="$emit('query',{page:pagination.current_page + 1})"><ChevronRight :size="17"/></button></div></div></section></section></template>
